//! Identical CFG construction/order with explicit caller-paid actual storage.
use super::*;

pub(super) fn build<'a>(
    function: &'a ResolvedFunction,
    work: &mut WorkCounter,
) -> Result<Cfg<'a>, Diagnostic> {
    let payer = work.allocation.ok_or_else(storage::marker)?;
    let mut roots = cfg_directory::fresh(payer)?;
    storage::extend(
        &mut roots,
        function
            .requires
            .iter()
            .chain(std::iter::once(&function.body))
            .chain(function.ensures.iter()),
        work.allocation,
    )?;
    let mut expressions = cfg_directory::fresh(payer)?;
    let mut seen = cfg_directory::Set::new(payer)?;
    let mut root_by_expression = cfg_directory::Map::<ExpressionId, ExpressionId>::new(payer)?;
    let mut pending = cfg_directory::fresh(payer)?;
    storage::extend(
        &mut pending,
        roots.iter().rev().map(|root| (*root, *root)),
        work.allocation,
    )?;
    let mut child_scratch: Option<Vec<&'a ResolvedExpr>> = None;
    while let Some((expression, root)) = pending.pop() {
        charge(work)?;
        if !cfg_directory::set_insert(&mut seen, expression.id.clone(), work.allocation)? {
            return Err(error("CFG contains a duplicate expression identity"));
        }
        cfg_directory::map_insert(
            &mut root_by_expression,
            expression.id.clone(),
            root.id.clone(),
            work.allocation,
        )?;
        storage::push(&mut expressions, expression, work.allocation)?;
        // Acquire at the original child frontier, after work/identity checks.
        // Only borrowed references enter this one invocation-owned scratch.
        if child_scratch.is_none() {
            child_scratch = Some(cfg_directory::fresh(payer)?);
        } else {
            payer.reserve(0).map_err(|_| storage::marker())?;
        }
        let children = child_scratch.as_mut().expect("child scratch acquired");
        children.clear();
        paid_children::push_children(expression, children, work.allocation)?;
        storage::extend(
            &mut pending,
            children.iter().copied().map(|child| (child, root)),
            work.allocation,
        )?;
        children.clear();
    }
    // No scratch backing is retained in the returned CFG or point phase.
    drop(child_scratch);
    let node_count = expressions
        .len()
        .checked_mul(2)
        .ok_or_else(|| error("CFG point count overflows"))?;
    if node_count > MAX_LOAN_ENDPOINTS_V1 {
        return Err(error("function exceeds 4,096 loan program points"));
    }
    let mut points = cfg_directory::vector(node_count, payer)?;
    let mut nodes = cfg_directory::Map::new(payer)?;
    for expression in &expressions {
        for phase in [LoanPointPhase::Before, LoanPointPhase::After] {
            let point = point(expression, phase);
            let id =
                u16::try_from(points.len()).map_err(|_| error("CFG point identity overflows"))?;
            cfg_directory::map_insert(&mut nodes, point.clone(), id, work.allocation)?;
            storage::push(&mut points, point, work.allocation)?;
        }
    }
    let node = |expression: &ResolvedExpr, phase: LoanPointPhase| {
        nodes
            .get(&point(expression, phase))
            .copied()
            .ok_or_else(|| error("CFG child point is not indexed"))
    };
    let root_after = |expression: &ResolvedExpr| {
        let root = root_by_expression
            .get(&expression.id)
            .ok_or_else(|| error("CFG expression lacks a function-exit root"))?;
        nodes
            .get(&LoanProgramPoint {
                expression: root.clone(),
                phase: LoanPointPhase::After,
            })
            .copied()
            .ok_or_else(|| error("CFG function-exit root is not indexed"))
    };
    let mut edge_set = cfg_directory::Set::<(u16, u16)>::new(payer)?;
    for expression in &expressions {
        charge(work)?;
        let before = node(expression, LoanPointPhase::Before)?;
        let after = node(expression, LoanPointPhase::After)?;
        match &expression.kind {
            ResolvedExprKind::LexicalExit { kind, value, .. } => {
                if let Some(value) = value {
                    cfg_directory::set_insert(
                        &mut edge_set,
                        (before, node(value, LoanPointPhase::Before)?),
                        work.allocation,
                    )?;
                    cfg_directory::set_insert(
                        &mut edge_set,
                        (node(value, LoanPointPhase::After)?, after),
                        work.allocation,
                    )?;
                } else {
                    cfg_directory::set_insert(&mut edge_set, (before, after), work.allocation)?;
                }
                let destination = if *kind == crate::ast::LexicalExitKind::Return {
                    root_after(expression)?
                } else {
                    node(
                        lexical_exit::destination(expression, &expressions, work)?,
                        LoanPointPhase::Before,
                    )?
                };
                cfg_directory::set_insert(&mut edge_set, (after, destination), work.allocation)?;
            }
            ResolvedExprKind::Block { statements, tail }
            | ResolvedExprKind::VecConstructor {
                statements, tail, ..
            } => {
                let entry = statements
                    .first()
                    .map(statement_entry)
                    .unwrap_or(tail.as_ref());
                cfg_directory::set_insert(
                    &mut edge_set,
                    (before, node(entry, LoanPointPhase::Before)?),
                    work.allocation,
                )?;
                for (index, statement) in statements.iter().enumerate() {
                    let next = statements
                        .get(index + 1)
                        .map(statement_entry)
                        .unwrap_or(tail.as_ref());
                    match statement {
                        ResolvedStatement::While {
                            condition, body, ..
                        }
                        | ResolvedStatement::LexicalWhile {
                            condition, body, ..
                        } => {
                            cfg_directory::set_insert(
                                &mut edge_set,
                                (
                                    node(condition, LoanPointPhase::After)?,
                                    node(body, LoanPointPhase::Before)?,
                                ),
                                work.allocation,
                            )?;
                            cfg_directory::set_insert(
                                &mut edge_set,
                                (
                                    node(condition, LoanPointPhase::After)?,
                                    node(next, LoanPointPhase::Before)?,
                                ),
                                work.allocation,
                            )?;
                            if body.ty != ResolvedType::Never {
                                cfg_directory::set_insert(
                                    &mut edge_set,
                                    (
                                        node(body, LoanPointPhase::After)?,
                                        node(condition, LoanPointPhase::Before)?,
                                    ),
                                    work.allocation,
                                )?;
                            }
                        }
                        _ => {
                            cfg_directory::set_insert(
                                &mut edge_set,
                                (
                                    node(statement_exit(statement), LoanPointPhase::After)?,
                                    node(next, LoanPointPhase::Before)?,
                                ),
                                work.allocation,
                            )?;
                        }
                    }
                }
                if tail.ty != ResolvedType::Never {
                    cfg_directory::set_insert(
                        &mut edge_set,
                        (node(tail, LoanPointPhase::After)?, after),
                        work.allocation,
                    )?;
                }
            }
            ResolvedExprKind::If {
                condition,
                then_branch,
                else_branch,
            } => {
                cfg_directory::set_insert(
                    &mut edge_set,
                    (before, node(condition, LoanPointPhase::Before)?),
                    work.allocation,
                )?;
                cfg_directory::set_insert(
                    &mut edge_set,
                    (
                        node(condition, LoanPointPhase::After)?,
                        node(then_branch, LoanPointPhase::Before)?,
                    ),
                    work.allocation,
                )?;
                cfg_directory::set_insert(
                    &mut edge_set,
                    (
                        node(condition, LoanPointPhase::After)?,
                        node(else_branch, LoanPointPhase::Before)?,
                    ),
                    work.allocation,
                )?;
                if then_branch.ty != ResolvedType::Never {
                    cfg_directory::set_insert(
                        &mut edge_set,
                        (node(then_branch, LoanPointPhase::After)?, after),
                        work.allocation,
                    )?;
                }
                if else_branch.ty != ResolvedType::Never {
                    cfg_directory::set_insert(
                        &mut edge_set,
                        (node(else_branch, LoanPointPhase::After)?, after),
                        work.allocation,
                    )?;
                }
            }
            ResolvedExprKind::Binary {
                op: BinaryOp::And | BinaryOp::Or,
                left,
                right,
            } => {
                cfg_directory::set_insert(
                    &mut edge_set,
                    (before, node(left, LoanPointPhase::Before)?),
                    work.allocation,
                )?;
                cfg_directory::set_insert(
                    &mut edge_set,
                    (
                        node(left, LoanPointPhase::After)?,
                        node(right, LoanPointPhase::Before)?,
                    ),
                    work.allocation,
                )?;
                cfg_directory::set_insert(
                    &mut edge_set,
                    (node(left, LoanPointPhase::After)?, after),
                    work.allocation,
                )?;
                cfg_directory::set_insert(
                    &mut edge_set,
                    (node(right, LoanPointPhase::After)?, after),
                    work.allocation,
                )?;
            }
            ResolvedExprKind::Match {
                scrutinee, arms, ..
            } => {
                cfg_directory::set_insert(
                    &mut edge_set,
                    (before, node(scrutinee, LoanPointPhase::Before)?),
                    work.allocation,
                )?;
                for (index, arm) in arms.iter().enumerate() {
                    let entry = arm.guard.as_deref().unwrap_or(&arm.value);
                    cfg_directory::set_insert(
                        &mut edge_set,
                        (
                            node(scrutinee, LoanPointPhase::After)?,
                            node(entry, LoanPointPhase::Before)?,
                        ),
                        work.allocation,
                    )?;
                    if let Some(guard) = &arm.guard {
                        cfg_directory::set_insert(
                            &mut edge_set,
                            (
                                node(guard, LoanPointPhase::After)?,
                                node(&arm.value, LoanPointPhase::Before)?,
                            ),
                            work.allocation,
                        )?;
                        if let Some(next) = arms.get(index + 1) {
                            let next = next.guard.as_deref().unwrap_or(&next.value);
                            cfg_directory::set_insert(
                                &mut edge_set,
                                (
                                    node(guard, LoanPointPhase::After)?,
                                    node(next, LoanPointPhase::Before)?,
                                ),
                                work.allocation,
                            )?;
                        }
                    }
                    if arm.value.ty != ResolvedType::Never {
                        cfg_directory::set_insert(
                            &mut edge_set,
                            (node(&arm.value, LoanPointPhase::After)?, after),
                            work.allocation,
                        )?;
                    }
                }
            }
            ResolvedExprKind::Try { operand, .. } | ResolvedExprKind::TryOption { operand, .. } => {
                let operand_after = node(operand, LoanPointPhase::After)?;
                cfg_directory::set_insert(
                    &mut edge_set,
                    (before, node(operand, LoanPointPhase::Before)?),
                    work.allocation,
                )?;
                cfg_directory::set_insert(&mut edge_set, (operand_after, after), work.allocation)?;
                // `?` has two semantic successors: normal unwrapping and an
                // immediate residual return from this contract/body root.
                // Keeping the residual edge distinct makes a later loan use
                // live only on the normal path and terminates it on return.
                cfg_directory::set_insert(
                    &mut edge_set,
                    (operand_after, root_after(expression)?),
                    work.allocation,
                )?;
            }
            _ => {
                let mut children = evaluation_children(expression);
                if let Some(first) = children.next() {
                    cfg_directory::set_insert(
                        &mut edge_set,
                        (before, node(first, LoanPointPhase::Before)?),
                        work.allocation,
                    )?;
                    let mut last = first;
                    for next in children {
                        cfg_directory::set_insert(
                            &mut edge_set,
                            (
                                node(last, LoanPointPhase::After)?,
                                node(next, LoanPointPhase::Before)?,
                            ),
                            work.allocation,
                        )?;
                        last = next;
                    }
                    cfg_directory::set_insert(
                        &mut edge_set,
                        (node(last, LoanPointPhase::After)?, after),
                        work.allocation,
                    )?;
                } else {
                    cfg_directory::set_insert(&mut edge_set, (before, after), work.allocation)?;
                }
            }
        }
    }
    let edges = edge_set.into_vec(payer)?;
    if edges.len() > MAX_LOAN_EDGES_V1 {
        return Err(error("function exceeds 4,096 loan CFG edges"));
    }
    payer
        .reserve(std::mem::size_of::<adjacency::Adjacency>())
        .map_err(|_| storage::marker())?;
    let adjacency =
        adjacency::Adjacency::build_with_storage(points.len(), &edges, work.allocation)?;
    payer
        .reserve(std::mem::size_of::<Cfg<'_>>())
        .map_err(|_| storage::marker())?;
    Ok(Cfg {
        points,
        nodes: cfg_directory::Nodes::Funded(nodes),
        expressions,
        edges,
        adjacency,
    })
}

//! Full prior/current CFG controls for removal of one redundant identity tree.
use super::*;
use crate::bounded_output::cfg_reservation::CfgReservation;
use crate::bounded_output::{reserve_active_required, with_limit_usage_refusal};
use crate::test_allocation_observer::{current_metrics, measure, Metrics};

fn fixture(width: usize, depth: usize) -> ResolvedProgram {
    let mut source = String::from("module cfg.rootmap; @id(\"cfg.main\") fn main()->i64 {");
    for i in 0..width {
        source.push_str(&format!("let value{i}=1;"));
    }
    source.push('1');
    for _ in 0..depth {
        source.push_str("+1");
    }
    source.push('}');
    crate::hir::resolve(&crate::check(&source, "cfg-rootmap.spx").unwrap()).unwrap()
}
fn same_cfg(a: &Cfg<'_>, b: &Cfg<'_>) {
    let Cfg {
        points,
        nodes,
        expressions,
        edges,
        adjacency,
    } = a;
    assert_eq!(points, &b.points);
    assert_eq!(edges, &b.edges);
    assert_eq!(expressions, &b.expressions);
    assert_eq!(
        nodes.complete_len_for_test(),
        b.nodes.complete_len_for_test()
    );
    for point in points {
        assert_eq!(nodes.get(point), b.nodes.get(point));
    }
    assert!(adjacency.complete_storage_matches_for_test(&b.adjacency));
    for (left, right) in expressions.iter().zip(&b.expressions) {
        assert!(std::ptr::eq(*left, *right));
    }
}
fn run<'a>(
    f: &'a ResolvedFunction,
    work: &mut WorkCounter,
    old: bool,
) -> Result<Cfg<'a>, Diagnostic> {
    if old {
        seen_before::build(f, work)
    } else {
        build(f, work)
    }
}
#[test]
fn rootmap_identity_membership_preserves_complete_old_cfg_and_every_work_boundary() {
    for (width, depth) in [(0, 0), (17, 32), (129, 1)] {
        let program = fixture(width, depth);
        let function = &program.functions[0];
        let ((), refused, _, first) = with_limit_usage_refusal(usize::MAX, || {
            let owner = CfgReservation::acquire().unwrap();
            let mut old_work = WorkCounter::new(MAX_LOAN_PLAN_WORK_V1);
            old_work.allocation = Some(&owner);
            let old = seen_before::build(function, &mut old_work).unwrap();
            let mut current_work = WorkCounter::new(MAX_LOAN_PLAN_WORK_V1);
            current_work.allocation = Some(&owner);
            let current = build(function, &mut current_work).unwrap();
            same_cfg(&current, &old);
            assert_eq!(current_work.used, old_work.used);
            for limit in 0..=old_work.used {
                let mut a = WorkCounter::new(limit);
                a.allocation = Some(&owner);
                let mut b = WorkCounter::new(limit);
                b.allocation = Some(&owner);
                let current = build(function, &mut a);
                let old = seen_before::build(function, &mut b);
                assert_eq!(a.used, b.used);
                match (current, old) {
                    (Ok(a), Ok(b)) => same_cfg(&a, &b),
                    (Err(a), Err(b)) => assert_eq!(a, b, "complete work refusal receipt"),
                    _ => panic!("complete old/current outcome differs at work limit {limit}"),
                }
            }
            assert_eq!(owner.first(), None);
        });
        assert!(!refused);
        assert_eq!(first, None);
    }
}
#[test]
fn rootmap_identity_membership_keeps_duplicate_identity_first_error_and_work_order() {
    let mut program = fixture(2, 3);
    let function = &mut program.functions[0];
    let ResolvedExprKind::Block { tail, .. } = &mut function.body.kind else {
        panic!("block")
    };
    let ResolvedExprKind::Binary { left, right, .. } = &mut tail.kind else {
        panic!("binary")
    };
    right.id = left.id.clone();
    let ((), refused, _, first) = with_limit_usage_refusal(usize::MAX, || {
        let owner = CfgReservation::acquire().unwrap();
        for limit in [0, 1, 2, 3, 4, MAX_LOAN_PLAN_WORK_V1] {
            let mut a = WorkCounter::new(limit);
            a.allocation = Some(&owner);
            let mut b = WorkCounter::new(limit);
            b.allocation = Some(&owner);
            let current = build(function, &mut a)
                .err()
                .expect("duplicate or earlier work refusal");
            let old = seen_before::build(function, &mut b)
                .err()
                .expect("full old refusal");
            assert_eq!(
                current, old,
                "all diagnostic fields at competing work/identity errors"
            );
            assert_eq!(a.used, b.used);
            if limit == MAX_LOAN_PLAN_WORK_V1 {
                assert_eq!(
                    current.message,
                    "CFG contains a duplicate expression identity"
                );
            }
            assert_eq!(owner.first(), None);
        }
    });
    assert!(!refused);
    assert_eq!(first, None);
}
fn observe(
    function: &ResolvedFunction,
    old: bool,
    limit: usize,
) -> (
    (bool, Metrics),
    bool,
    usize,
    Option<crate::bounded_output::ReservationRefusal>,
) {
    with_limit_usage_refusal(limit, || {
        measure(|| {
            let owner = match CfgReservation::acquire() {
                Ok(owner) => owner,
                Err(_) => {
                    assert!(!reserve_active_required(0));
                    return false;
                }
            };
            let mut work = WorkCounter::new(MAX_LOAN_PLAN_WORK_V1);
            work.allocation = Some(&owner);
            match run(function, &mut work, old) {
                Ok(cfg) => {
                    drop(cfg);
                    assert_eq!(owner.first(), None);
                    drop(owner);
                    true
                }
                Err(error) => {
                    let first = owner
                        .first()
                        .expect("positive fixture only physically refuses");
                    let at_stop = current_metrics().allocated;
                    assert_eq!(owner.reserve(0), Err(first));
                    assert_eq!(owner.reserve(1), Err(first));
                    let used = work.used;
                    let retry = run(function, &mut work, old);
                    assert!(retry.is_err());
                    assert_eq!(work.used, used);
                    assert_eq!(owner.first(), Some(first));
                    drop(retry);
                    drop(error);
                    drop(owner);
                    assert_eq!(
                        current_metrics().allocated,
                        at_stop,
                        "no allocation after selected error or during Drop"
                    );
                    false
                }
            }
        })
    })
}
#[test]
fn rootmap_identity_membership_removes_one_actual_box_per_expression_and_funds_drop() {
    for (width, depth) in [(0, 0), (17, 32), (129, 1)] {
        let program = fixture(width, depth);
        let function = &program.functions[0];
        let (count, refused, _, _) = with_limit_usage_refusal(usize::MAX, || {
            let owner = CfgReservation::acquire().unwrap();
            let mut work = WorkCounter::new(MAX_LOAN_PLAN_WORK_V1);
            work.allocation = Some(&owner);
            build(function, &mut work).unwrap().expressions.len()
        });
        assert!(!refused);
        let ((old_ok, old), old_refused, old_paid, _) = observe(function, true, usize::MAX);
        let ((ok, current), refused, exact, first) = observe(function, false, usize::MAX);
        assert!(old_ok && ok && !old_refused && !refused);
        assert_eq!(first, None);
        assert_eq!(
            old.allocations - current.allocations,
            count,
            "one removed actual AVL Box per unique expression"
        );
        assert!(old.allocated > current.allocated && old_paid > exact);
        for metrics in [old, current] {
            assert!(!metrics.invalid);
            assert_eq!(metrics.live, 0);
            assert_eq!(metrics.allocated, metrics.freed);
        }
        assert!(current.allocated <= exact);
        assert!(old.allocated <= old_paid);
        for cap in [0, exact - 1, exact] {
            let ((ok, metrics), refused, used, first) = observe(function, false, cap);
            assert_eq!(ok, cap == exact);
            assert_eq!(refused, cap != exact);
            assert!(!metrics.invalid);
            assert_eq!(metrics.live, 0);
            assert_eq!(metrics.allocated, metrics.freed);
            if cap == exact {
                assert_eq!(used, exact);
                assert_eq!(first, None);
                assert!(metrics.allocated <= used);
            } else {
                assert!(first.is_some());
                if cap == 0 {
                    assert_eq!(metrics.allocated, 0);
                }
            }
        }
    }
}
